func stageDurationSeconds(st *StageState) float64 {
        if st == nil || st.StartTime == "" || st.EndTime == "" {
                return 0
        }
        start, err1 := time.Parse(time.RFC3339, st.StartTime)
        end, err2 := time.Parse(time.RFC3339, st.EndTime)
        if err1 != nil || err2 != nil {
                return 0
        }
        if end.Before(start) {
                return 0
        }
        return end.Sub(start).Seconds()
}

