status_code = r'''
type statusStage struct {
        Name            string  `json:"name"`
        Status          string  `json:"status"`
        ExitCode        int     `json:"exit_code"`
        Retries         int     `json:"retries"`
        DurationSeconds float64 `json:"duration_seconds"`
}

type statusExperiment struct {
        ID                   string            `json:"id"`
        Status               string            `json:"status"`
        Stages               []statusStage     `json:"stages"`
        CompletedStages      int               `json:"completed_stages"`
        TotalStages          int               `json:"total_stages"`
        TotalDurationSeconds float64           `json:"total_duration_seconds"`
        Parameters           map[string]string `json:"parameters"`
}

type stageSummaryEntry struct {
        Completed          int     `json:"completed"`
        Failed             int     `json:"failed"`
        Skipped            int     `json:"skipped"`
        Pending            int     `json:"pending"`
        MeanDurationSeconds float64 `json:"mean_duration_seconds"`
        MaxDurationSeconds  float64 `json:"max_duration_seconds"`
}

type paramBreakdownValue struct {
        Completed int `json:"completed"`
        Failed    int `json:"failed"`
        Pending   int `json:"pending"`
}

type statusHealth struct {
        CompletionRate          float64 `json:"completion_rate"`
        FailureRate             float64 `json:"failure_rate"`
        MostFailedStage         *string `json:"most_failed_stage"`
        SlowestStage            *string `json:"slowest_stage"`
        EstimatedRemainingSeconds float64 `json:"estimated_remaining_seconds"`
}

type statusOutput struct {
        Pipeline            string                              `json:"pipeline"`
        TotalExperiments    int                                 `json:"total_experiments"`
        CompletedExperiments int                                `json:"completed_experiments"`
        FailedExperiments   int                                 `json:"failed_experiments"`
        PendingExperiments  int                                 `json:"pending_experiments"`
        Experiments         []statusExperiment                  `json:"experiments"`
        StageSummary        map[string]stageSummaryEntry        `json:"stage_summary"`
        ParameterBreakdown  map[string]map[string]paramBreakdownValue `json:"parameter_breakdown"`
        Health              statusHealth                        `json:"health"`
}

func cmdStatus(args []string) int {
        pipelineFile := ""
        filterStatus := ""
        stageFilter := ""
        for i := 0; i < len(args); i++ {
                arg := args[i]
                switch {
                case arg == "--filter-status":
                        if i+1 >= len(args) {
                                fmt.Fprintln(os.Stderr, "error: --filter-status requires a value")
                                return 1
                        }
                        i++
                        filterStatus = args[i]
                case strings.HasPrefix(arg, "--filter-status="):
                        filterStatus = strings.TrimPrefix(arg, "--filter-status=")
                case arg == "--stage":
                        if i+1 >= len(args) {
                                fmt.Fprintln(os.Stderr, "error: --stage requires a value")
                                return 1
                        }
                        i++
                        stageFilter = args[i]
                case strings.HasPrefix(arg, "--stage="):
                        stageFilter = strings.TrimPrefix(arg, "--stage=")
                case pipelineFile == "":
                        pipelineFile = arg
                default:
                        fmt.Fprintf(os.Stderr, "error: unknown argument %q\n", arg)
                        return 1
                }
        }
        if pipelineFile == "" {
                fmt.Fprintln(os.Stderr, "Usage: mlpipe status <pipeline.yaml> [--filter-status <status>] [--stage <name>]")
                return 1
        }
        if filterStatus != "" && filterStatus != "completed" && filterStatus != "failed" && filterStatus != "pending" && filterStatus != "running" {
                fmt.Fprintf(os.Stderr, "error: invalid filter status %q\n", filterStatus)
                return 1
        }
        p, err := loadPipeline(pipelineFile)
        if err != nil {
                fmt.Fprintln(os.Stderr, "error:", err)
                return 1
        }
        if errs := validatePipeline(p); len(errs) > 0 {
                for _, e := range errs {
                        fmt.Fprintln(os.Stderr, e)
                }
                return 1
        }
        stageNames, err := pipelineStageNames(p)
        if err != nil {
                fmt.Fprintln(os.Stderr, "error:", err)
                return 1
        }
        if stageFilter != "" {
                found := false
                for _, name := range stageNames {
                        if name == stageFilter {
                                found = true
                                break
                        }
                }
                if !found {
                        fmt.Fprintf(os.Stderr, "error: stage %q not found in pipeline\n", stageFilter)
                        return 1
                }
        }

        expected := expectedExperimentIDs(p)
        sort.Strings(expected)

        type expInfo struct {
                id       string
                params   map[string]string
                stages   []statusStage
                status   string
                totalDur float64
        }
        infos := make([]expInfo, 0, len(expected))
        stageFailCounts := map[string]int{}
        stageDurations := map[string][]float64{}
        stagePending := map[string]int{}
        stageSkipped := map[string]int{}
        stageCompleted := map[string]int{}
        stageFailed := map[string]int{}
        for _, stage := range stageNames {
                stageFailCounts[stage] = 0
                stageDurations[stage] = []float64{}
                stagePending[stage] = 0
                stageSkipped[stage] = 0
                stageCompleted[stage] = 0
                stageFailed[stage] = 0
        }

        completedExperiments := 0
        failedExperiments := 0
        pendingExperiments := 0
        totalDurCompleted := 0.0
        completedCount := 0

        for _, id := range expected {
                params := extractExperimentParams(p, id)
                stages := []statusStage{}
                hasAnyState := false
                anyRunning := false
                anyFailed := false
                allCompletedOrSkipped := true
                completedStages := 0
                totalDur := 0.0

                for _, stage := range stageNames {
                        if stageFilter != "" && stage != stageFilter {
                                // Still compute summary below by reading state even if filtered out of display.
                        }
                        st, err := readStageState(id, stage)
                        if err != nil {
                                stages = append(stages, statusStage{Name: stage, Status: "pending", ExitCode: -1, Retries: 0, DurationSeconds: 0})
                                stagePending[stage]++
                                if allCompletedOrSkipped {
                                        allCompletedOrSkipped = false
                                }
                                continue
                        }
                        hasAnyState = true
                        dur := round1(stageDurationSeconds(st))
                        totalDur += dur
                        status := st.Status
                        if status == "" {
                                status = "pending"
                        }
                        exitCode := st.ExitCode
                        if status == "pending" {
                                exitCode = -1
                        }
                        stages = append(stages, statusStage{Name: stage, Status: status, ExitCode: exitCode, Retries: st.Retries, DurationSeconds: dur})
                        switch status {
                        case "completed":
                                stageCompleted[stage]++
                                completedStages++
                                stageDurations[stage] = append(stageDurations[stage], dur)
                        case "skipped":
                                stageSkipped[stage]++
                        case "failed":
                                stageFailed[stage]++
                                stageFailCounts[stage]++
                                anyFailed = true
                                allCompletedOrSkipped = false
                        case "running":
                                anyRunning = true
                                allCompletedOrSkipped = false
                        default:
                                stagePending[stage]++
                                allCompletedOrSkipped = false
                        }
                }

                status := "pending"
                if !hasAnyState && len(stages) == 0 {
                        status = "pending"
                } else if anyFailed {
                        status = "failed"
                } else if anyRunning {
                        status = "running"
                } else if allCompletedOrSkipped {
                        status = "completed"
                } else {
                        status = "pending"
                }
                _ = hasAnyState

                switch status {
                case "completed":
                        completedExperiments++
                        completedCount++
                        totalDurCompleted += totalDur
                case "failed":
                        failedExperiments++
                case "pending":
                        pendingExperiments++
                }

                infos = append(infos, expInfo{id: id, params: params, stages: stages, status: status, totalDur: round1(totalDur)})
        }

        out := statusOutput{
                Pipeline:             p.Name,
                TotalExperiments:     len(expected),
                CompletedExperiments: completedExperiments,
                FailedExperiments:    failedExperiments,
                PendingExperiments:   pendingExperiments,
                Experiments:           []statusExperiment{},
                StageSummary:          map[string]stageSummaryEntry{},
                ParameterBreakdown:    map[string]map[string]paramBreakdownValue{},
        }

        for _, info := range infos {
                if filterStatus != "" && info.status != filterStatus {
                        continue
                }
                stages := info.stages
                if stageFilter != "" {
                        filtered := []statusStage{}
                        for _, st := range stages {
                                if st.Name == stageFilter {
                                        filtered = append(filtered, st)
                                }
                        }
                        stages = filtered
                }
                out.Experiments = append(out.Experiments, statusExperiment{
                        ID:                   info.id,
                        Status:               info.status,
                        Stages:               stages,
                        CompletedStages:      countCompletedStages(info.stages),
                        TotalStages:          len(stageNames),
                        TotalDurationSeconds: info.totalDur,
                        Parameters:           info.params,
                })
        }

        for _, stage := range stageNames {
                meanDur := 0.0
                if len(stageDurations[stage]) > 0 {
                        meanDur = meanValue(stageDurations[stage])
                }
                maxDur := 0.0
                if len(stageDurations[stage]) > 0 {
                        maxDur = maxValue(stageDurations[stage])
                }
                out.StageSummary[stage] = stageSummaryEntry{
                        Completed:            stageCompleted[stage],
                        Failed:               stageFailed[stage],
                        Skipped:              stageSkipped[stage],
                        Pending:              stagePending[stage],
                        MeanDurationSeconds:  round1(meanDur),
                        MaxDurationSeconds:   round1(maxDur),
                }
        }

        // Parameter breakdown
        paramNames := []string{}
        for _, param := range p.Parameters {
                paramNames = append(paramNames, param.Name)
        }
        sort.Strings(paramNames)
        for _, name := range paramNames {
                out.ParameterBreakdown[name] = map[string]paramBreakdownValue{}
        }
        for _, info := range infos {
                for _, name := range paramNames {
                        val := info.params[name]
                        if _, ok := out.ParameterBreakdown[name]; !ok {
                                out.ParameterBreakdown[name] = map[string]paramBreakdownValue{}
                        }
                        entry := out.ParameterBreakdown[name][val]
                        switch info.status {
                        case "completed":
                                entry.Completed++
                        case "failed":
                                entry.Failed++
                        case "pending":
                                entry.Pending++
                        }
                        out.ParameterBreakdown[name][val] = entry
                }
        }
        // Sort parameter values alphabetically by using sorted keys and rebuilding maps.
        for name, vals := range out.ParameterBreakdown {
                keys := make([]string, 0, len(vals))
                for k := range vals {
                        keys = append(keys, k)
                }
                sort.Strings(keys)
                sortedVals := map[string]paramBreakdownValue{}
                for _, k := range keys {
                        sortedVals[k] = vals[k]
                }
                out.ParameterBreakdown[name] = sortedVals
        }

        // Health
        completionRate := 0.0
        failureRate := 0.0
        if len(expected) > 0 {
                completionRate = float64(completedExperiments) / float64(len(expected))
                failureRate = float64(failedExperiments) / float64(len(expected))
        }
        var mostFailed *string
        maxFail := -1
        for _, stage := range stageNames {
                cnt := stageFailCounts[stage]
                if cnt > 0 && cnt > maxFail {
                        maxFail = cnt
                        name := stage
                        mostFailed = &name
                }
        }
        var slowest *string
        maxMean := -1.0
        for _, stage := range stageNames {
                mean := 0.0
                if len(stageDurations[stage]) > 0 {
                        mean = meanValue(stageDurations[stage])
                }
                if len(stageDurations[stage]) > 0 && mean > maxMean {
                        maxMean = mean
                        name := stage
                        slowest = &name
                }
        }
        estimatedRemaining := 0.0
        if pendingExperiments > 0 && completedCount > 0 {
                estimatedRemaining = (totalDurCompleted / float64(completedCount)) * float64(pendingExperiments)
        }
        out.Health = statusHealth{
                CompletionRate:             round4(completionRate),
                FailureRate:                round4(failureRate),
                MostFailedStage:            mostFailed,
                SlowestStage:               slowest,
                EstimatedRemainingSeconds: round1(estimatedRemaining),
        }

        enc := json.NewEncoder(os.Stdout)
        enc.SetIndent("", "  ")
        if err := enc.Encode(out); err != nil {
                fmt.Fprintln(os.Stderr, "error:", err)
                return 1
        }
        return 0
}

func countCompletedStages(stages []statusStage) int {
        n := 0
        for _, s := range stages {
                if s.Status == "completed" {
                        n++
                }
        }
        return n
}
